    if [[ -z "$output" ]]; then
        echo "No retained builds for $JENKINS_JOB"
    else
        printf '%s\n' "$output"
    fi
}

main() {
    (($# >= 1)) || { usage; exit 2; }
    if (($# == 2)) && [[ "$2" == -h || "$2" == --help ]]; then
        case "$1" in start|run|active|recent|status|follow|abort) command_usage "$1"; return;; esac
    fi
